import React, { useEffect, useState } from "react";
import {
  LineChart, Line,
  PieChart, Pie, Cell,
  BarChart, Bar,
  XAxis, YAxis, Tooltip, Legend,
  ResponsiveContainer
} from "recharts";
import axios from "axios";

export default function AnalyticsDashboard() {
  const [summary, setSummary] = useState({});
  const [statusData, setStatusData] = useState([]);
  const [trendData, setTrendData] = useState([]);
  const [driverData, setDriverData] = useState([]);

  useEffect(() => {
    async function fetchStats() {
      const [{ data: deliveries }, { data: drivers }] = await Promise.all([
        axios.get("/api/delivery"),
        axios.get("/api/drivers")
      ]);

      // 1. Summary
      const total = deliveries.length;
      const completed = deliveries.filter(d => d.status === "Delivered").length;
      const pending = deliveries.filter(d => d.status === "Pending").length;
      const inTransit = deliveries.filter(d => d.status === "In Transit").length;
      // assume each delivery has duration in minutes
      const avgTime = (deliveries.reduce((sum, d) => sum + (d.duration||0), 0) / total).toFixed(1);

      setSummary({ total, completed, pending, inTransit, successRate: ((completed/total)*100).toFixed(1), avgTime });

      // 2. Status distribution
      setStatusData([
        { name: "Delivered", value: completed },
        { name: "In Transit", value: inTransit },
        { name: "Pending", value: pending }
      ]);

      // 3. Trend: group by day
      const byDate = {};
      deliveries.forEach(d => {
        const day = d.createdAt.slice(0,10);
        byDate[day] = (byDate[day]||0) + 1;
      });
      setTrendData(Object.entries(byDate).map(([date,count])=>({ date, count })));

      // 4. Driver utilization
      const driverMap = {};
      deliveries.forEach(d => {
        if (d.status === "Delivered") {
          driverMap[d.driverId] = (driverMap[d.driverId]||0) + 1;
        }
      });
      setDriverData(Object.entries(driverMap).map(([id,count])=>({ driver: id, count })));
    }
    fetchStats();
  }, []);

  const COLORS = ["#28a745", "#ffc107", "#dc3545"];

  return (
    <div style={{ padding: 20 }}>
      {/* Summary cards */}
      <div style={{ display:'flex', gap:20, marginBottom:40 }}>
        {[
          { label:"Total Deliveries", value: summary.total },
          { label:"Completed",        value: summary.completed },
          { label:"Pending",          value: summary.pending },
          { label:"In Transit",       value: summary.inTransit },
          { label:"Success Rate",     value: summary.successRate + "%" },
          { label:"Avg Delivery Time",value: summary.avgTime + "m" }
        ].map((card,i)=>(
          <div key={i} style={{ flex:1, padding:20, background:"#fff", borderRadius:8, boxShadow:"0 2px 6px rgba(0,0,0,0.1)" }}>
            <h4>{card.label}</h4>
            <p style={{ fontSize:24, fontWeight:500 }}>{card.value}</p>
          </div>
        ))}
      </div>

      <div style={{ display:'flex', gap:40 }}>
        {/* Status Pie */}
        <ResponsiveContainer width="30%" height={300}>
          <PieChart>
            <Pie data={statusData} dataKey="value" nameKey="name" innerRadius={60} outerRadius={100}>
              {statusData.map((_, i) => <Cell key={i} fill={COLORS[i]} />)}
            </Pie>
            <Tooltip/>
            <Legend/>
          </PieChart>
        </ResponsiveContainer>

        {/* Trend Line */}
        <ResponsiveContainer width="70%" height={300}>
          <LineChart data={trendData}>
            <XAxis dataKey="date" />
            <YAxis />
            <Tooltip />
            <Line type="monotone" dataKey="count" stroke="#007bff" />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Driver Bar */}
      <div style={{ marginTop:40 }}>
        <h3>Driver Utilization</h3>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={driverData}>
            <XAxis dataKey="driver" />
            <YAxis />
            <Tooltip />
            <Bar dataKey="count" fill="#28a745" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
